func (this *Digifinex) fetchOrderBody(ch chan AsyncResult[Order], id string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	var marketType *string = nil
	var paramsMarketType any = nil
	marketType, paramsMarketType = this.HandleMarketTypeAndParams("fetchOrder", market, params)
	marginMode, query := this.HandleMarginModeAndParams("fetchOrder", paramsMarketType)
	var idValue *string = this.NumberToString(id)
	var request map[string]any = map[string]any{
		"order_id": idValue,
	}
	if marketType != nil && *marketType == "swap" {
		if market != nil {
			request["instrument_id"] = market["id"]
		}
	} else {
		request["market"] = marketType
	}
	var response map[string]any = nil
	var isMargin bool = (marginMode != nil) || (marketType != nil && *marketType == "margin")
	if isMargin {

		r1 := <-this.PrivateSpotGetMarginOrder(this.Extend(request, query))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else if marketType != nil && *marketType == "spot" {

		r2 := <-this.PrivateSpotGetSpotOrder(this.Extend(request, query))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	} else if marketType != nil && *marketType == "swap" {

		r3 := <-this.PrivateSwapGetTradeOrderInfo(this.Extend(request, query))
		if r3.Err != nil {
			panic(r3.Err)
		}
		response = r3.Value
	} else {
		panic(NotSupported(this.Id + " fetchOrder() not support this market type"))
	}
	//
	// spot and margin
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "symbol": "BTC_USDT",
	//                 "order_id": "dd3164b333a4afa9d5730bb87f6db8b3",
	//                 "created_date": 1562303547,
	//                 "finished_date": 0,
	//                 "price": 0.1,
	//                 "amount": 1,
	//                 "cash_amount": 1,
	//                 "executed_amount": 0,
	//                 "avg_price": 0,
	//                 "status": 1,
	//                 "type": "buy",
	//                 "kind": "margin"
	//             }
	//         ]
	//     }
	//
	// swap
	//
	//     {
	//         "code": 0,
	//         "data": {
	//             "order_id": "1590923061186531328",
	//             "instrument_id": "ETHUSDTPERP",
	//             "margin_mode": "crossed",
	//             "contract_val": "0.01",
	//             "type": 1,
	//             "order_type": 0,
	//             "price": "900",
	//             "size": "6",
	//             "filled_qty": "0",
	//             "price_avg": "0",
	//             "fee": "0",
	//             "state": 0,
	//             "leverage": "20",
	//             "turnover": "0",
	//             "has_stop": 0,
	//             "insert_time": 1668140590372,
	//             "time_stamp": 1668140590372
	//         }
	//     }
	//
	var data any = this.SafeValue(response, "data")
	var order any = func() any {
		if !isMargin && (marketType != nil && *marketType == "swap") {
			return data
		}
		return this.SafeValue(data, 0)
	}()
	if IsEqual(order, nil) {
		panic(OrderNotFound(this.Id + " fetchOrder() order " + *idValue + " not found"))
	}

	ch <- AsyncResult[Order]{Value: this.ParseOrder(order, market)}
	return nil
}

