func (this *Digifinex) ParseLedgerEntryType(typeVar *string) *string {
	var types map[string]any = map[string]any{}
	return this.SafeString(types, typeVar, typeVar)
}
func (this *Digifinex) ParseLedgerEntry(item any, optionalArgs ...any) LedgerEntry {
	//
	// spot and margin
	//
	//     {
	//         "currency_mark": "BTC",
	//         "type": 100234,
	//         "num": -10,
	//         "balance": 0.1,
	//         "time": 1546272000
	//     }
	//
	// swap
	//
	//     {
	//         "currency": "USDT",
	//         "finance_type": 17,
	//         "change": "-3.01",
	//         "timestamp": 1650809432000
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var typeVar *string = this.ParseLedgerEntryType(this.SafeString2(item, "type", "finance_type"))
	var currencyId *string = this.SafeString2(item, "currency_mark", "currency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var currencyResolved map[string]any = this.SafeCurrency(currencyId, currency)
	var amount *float64 = this.SafeNumber2(item, "num", "change")
	var after *float64 = this.SafeNumber(item, "balance")
	var timestamp *int64 = this.SafeTimestamp(item, "time")
	if timestamp == nil {
		timestamp = this.SafeInteger(item, "timestamp")
	}
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               nil,
		"direction":        nil,
		"account":          nil,
		"referenceId":      nil,
		"referenceAccount": nil,
		"type":             typeVar,
		"currency":         code,
		"amount":           amount,
		"before":           nil,
		"after":            after,
		"status":           nil,
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"fee":              nil,
	}, currencyResolved)
}

