func (this *Digifinex) ParseTransactionStatus(status *string) *string {
	// deposit state includes: 1 (in deposit), 2 (to be confirmed), 3 (successfully deposited), 4 (stopped)
	// withdrawal state includes: 1 (application in progress), 2 (to be confirmed), 3 (completed), 4 (rejected)
	var statuses map[string]any = map[string]any{
		"1": "pending",
		"2": "pending",
		"3": "ok",
		"4": "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Digifinex) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// withdraw
	//
	//     {
	//         "code": 200,
	//         "withdraw_id": 700
	//     }
	//
	// fetchDeposits, fetchWithdrawals
	//
	//     {
	//         "id": 1171,
	//         "currency": "xrp",
	//         "hash": "ed03094b84eafbe4bc16e7ef766ee959885ee5bcb265872baaa9c64e1cf86c2b",
	//         "chain": "",
	//         "amount": 7.457467,
	//         "address": "rae93V8d2mdoUQHwBDBdM4NHCMehRJAsbm",
	//         "memo": "100040",
	//         "fee": 0,
	//         "state": "safe",
	//         "created_date": "2020-04-20 11:23:00",
	//         "finished_date": "2020-04-20 13:23:00"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString2(transaction, "id", "withdraw_id")
	var address *string = this.SafeString(transaction, "address")
	var tag *string = this.SafeString(transaction, "memo")
	var txid *string = this.SafeString(transaction, "hash")
	var currencyId *string = this.SafeStringUpper(transaction, "currency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var timestamp *int64 = this.Parse8601(this.SafeString(transaction, "created_date"))
	var updated *int64 = this.Parse8601(this.SafeString(transaction, "finished_date"))
	var status *string = this.ParseTransactionStatus(this.SafeString(transaction, "state"))
	var amount *float64 = this.SafeNumber(transaction, "amount")
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	var fee map[string]any = nil
	if feeCost != nil {
		fee = map[string]any{
			"currency": code,
			"cost":     feeCost,
		}
	}
	var network *string = this.NetworkIdToCode(this.SafeString(transaction, "chain"), code)
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     network,
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         tag,
		"tagTo":       tag,
		"tagFrom":     nil,
		"type":        nil,
		"amount":      amount,
		"currency":    code,
		"status":      status,
		"updated":     updated,
		"internal":    nil,
		"comment":     nil,
		"fee":         fee,
	})
}
func (this *Digifinex) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"0": "ok",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Digifinex) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	// transfer between spot, margin and OTC
	//
	//     {
	//         "code": 0
	//     }
	//
	// transfer between spot and swap
	//
	//     {
	//         "code": 0,
	//         "data": {
	//             "type": 2,
	//             "currency": "USDT",
	//             "transfer_amount": "5"
	//         }
	//     }
	//
	// fetchTransfers
	//
	//     {
	//         "transfer_id": 130524,
	//         "type": 1,
	//         "currency": "USDT",
	//         "amount": "24",
	//         "timestamp": 1666505659000
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var fromAccount *string = nil
	var toAccount *string = nil
	var data any = this.SafeDict(transfer, "data", transfer)
	var typeVar *int64 = this.SafeInteger(data, "type")
	if typeVar != nil && *typeVar == 1 {
		fromAccount = SafeStringPtr("spot")
		toAccount = SafeStringPtr("swap")
	} else if typeVar != nil && *typeVar == 2 {
		fromAccount = SafeStringPtr("swap")
		toAccount = SafeStringPtr("spot")
	}
	var timestamp *int64 = this.SafeInteger(transfer, "timestamp")
	return TransferEntryFromMap(map[string]any{
		"info":        transfer,
		"id":          this.SafeString(transfer, "transfer_id"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"currency":    this.SafeCurrencyCode(this.SafeString(data, "currency"), currency),
		"amount":      this.SafeNumber2(data, "amount", "transfer_amount"),
		"fromAccount": fromAccount,
		"toAccount":   toAccount,
		"status":      this.ParseTransferStatus(this.SafeString(transfer, "code")),
	})
}

/**
 * @method
 * @name digifinex#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#transfer-assets-among-accounts
 * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#accounttransfer
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount 'spot', 'swap', 'margin', 'OTC' - account to transfer from
 * @param {string} toAccount 'spot', 'swap', 'margin', 'OTC' - account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Digifinex) TransferAsync(code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) <-chan AsyncResult[TransferEntry] {
	ch := make(chan AsyncResult[TransferEntry], 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Digifinex) transferBody(ch chan AsyncResult[TransferEntry], code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var currencyId *string = SafeStringPtr(currency["id"])
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	var fromId *string = this.SafeString(accountsByType, fromAccount, fromAccount)
	var toId *string = this.SafeString(accountsByType, toAccount, toAccount)
	var request map[string]any = map[string]any{}
	var fromSwap bool = (fromAccount == "swap")
	var toSwap bool = (toAccount == "swap")
	var response map[string]any = nil
	var amountString any = this.CurrencyToPrecision(code, amount)
	if fromSwap || toSwap {
		if (fromId == nil || *fromId != "1") && (toId == nil || *toId != "1") {
			panic(ExchangeError(this.Id + " transfer() supports transferring between spot and swap, spot and margin, spot and OTC only"))
		}
		request["type"] = func() int {
			if toSwap {
				return 1
			}
			return 2
		}() // 1 = spot to swap, 2 = swap to spot
		request["currency"] = currencyId
		request["transfer_amount"] = amountString
		//
		//     {
		//         "code": 0,
		//         "data": {
		//             "type": 2,
		//             "currency": "USDT",
		//             "transfer_amount": "5"
		//         }
		//     }
		//

		r1 := <-this.PrivateSwapPostAccountTransfer(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {
		request["currency_mark"] = currencyId
		request["num"] = amountString
		request["from"] = fromId // 1 = SPOT, 2 = MARGIN, 3 = OTC
		request["to"] = toId     // 1 = SPOT, 2 = MARGIN, 3 = OTC
		//
		//     {
		//         "code": 0
		//     }
		//

		r2 := <-this.PrivateSpotPostTransfer(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}
	if response == nil {
		panic(NullResponse(this.Id + " transfer() returned empty response"))
	}

	ch <- AsyncResult[TransferEntry]{Value: this.ParseTransfer(response, currency)}
	return nil
}

/**
 * @method
 * @name digifinex#withdraw
 * @description make a withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Digifinex) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Digifinex) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = nil
	tagWithdrawTag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	this.CheckAddress(address, code, tagWithdrawTag)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"address":  address,
		"amount":   this.CurrencyToPrecision(code, amount),
		"currency": currency["id"],
	}
	if tagWithdrawTag != nil {
		request["memo"] = *tagWithdrawTag
	}

	r1 := <-this.PrivateSpotPostWithdrawNew(this.Extend(request, paramsWithdrawTag))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "code": 200,
	//         "withdraw_id": 700
	//     }
	//
	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}
