func (this *Digifinex) ParseBorrowInterest(info any, optionalArgs ...any) any {
	//
	//     {
	//         "amount": 0.0006103,
	//         "side": "go_long",
	//         "entry_price": 31428.72,
	//         "liquidation_rate": 0.3,
	//         "liquidation_price": 10225.335481159,
	//         "unrealized_roe": -0.0076885829266987,
	//         "symbol": "BTC_USDT",
	//         "unrealized_pnl": -0.049158102631999,
	//         "leverage_ratio": 3
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(info, "symbol")
	var amountString *string = this.SafeString(info, "amount")
	var leverageString *string = this.SafeString(info, "leverage_ratio")
	var amountInvested *string = Precise.StringDiv(amountString, leverageString)
	var amountBorrowed *string = Precise.StringSub(amountString, amountInvested)
	var currency any = func() any {
		if market == nil {
			return nil
		}
		return market["base"]
	}()
	var symbol *string = this.SafeSymbol(marketId, market)
	return map[string]any{
		"info":           info,
		"symbol":         symbol,
		"currency":       currency,
		"interest":       nil,
		"interestRate":   0.001,
		"amountBorrowed": this.ParseNumber(amountBorrowed),
		"marginMode":     nil,
		"timestamp":      nil,
		"datetime":       nil,
	}
}

