func (this *Digifinex) fetchCrossBorrowRateBody(ch chan AsyncResult[CrossBorrowRate], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = map[string]any{}

	r1 := <-this.PrivateSpotGetMarginAssets(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "list": [
	//             {
	//                 "valuation_rate": 1,
	//                 "total": 1.92012186174,
	//                 "free": 1.92012186174,
	//                 "currency": "USDT"
	//             },
	//         ],
	//         "total": 45.133305540922,
	//         "code": 0,
	//         "unrealized_pnl": 0,
	//         "free": 45.133305540922,
	//         "equity": 45.133305540922
	//     }
	//
	var data []any = SafeListTyped(response, "list")
	var result any = nil
	for i := 0; i < len(data); i++ {
		var entry any = data[i]
		if this.SafeString(entry, "currency") != nil && *this.SafeString(entry, "currency") == code {
			result = entry
		}
	}
	var currency map[string]any = this.Currency(code)

	ch <- AsyncResult[CrossBorrowRate]{Value: CrossBorrowRateFromMap(this.ParseBorrowRate(result, currency))}
	return nil
}

