/**
 * @method
 * @name digifinex#fetchPositions
 * @description fetch all open positions
 * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#margin-positions
 * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#positions
 * @param {string[]|undefined} symbols list of unified market symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
 */
func (this *Digifinex) FetchPositionsAsync(optionalArgs ...any) <-chan AsyncResult[[]Position] {
	ch := make(chan AsyncResult[[]Position], 1)
	go this.fetchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Digifinex) fetchPositionsBody(ch chan AsyncResult[[]Position], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var request map[string]any = map[string]any{}
	var market map[string]any = nil
	var marketType *string = nil
	if symbolsNormalized != nil {
		var symbol any = nil
		if true {
			var symbolsLength int = len(symbolsNormalized)
			if symbolsLength > 1 {
				panic(BadRequest(this.Id + " fetchPositions() symbols argument cannot contain more than 1 symbol"))
			}
			symbol = func() any {
				if 0 >= 0 && 0 < len(symbolsNormalized) {
					return symbolsNormalized[0]
				}
				return nil
			}()
		} else {
			symbol = symbolsNormalized
		}
		market = this.Market(symbol)
	}
	var paramsMarketType any = nil
	marketType, paramsMarketType = this.HandleMarketTypeAndParams("fetchPositions", market, params)
	marginMode, query := this.HandleMarginModeAndParams("fetchPositions", paramsMarketType)
	if marginMode != nil {
		marketType = SafeStringPtr("margin")
	}
	if market != nil {
		var marketIdRequest string = "symbol"
		if marketType != nil && *marketType == "swap" {
			marketIdRequest = "instrument_id"
		}
		request[marketIdRequest] = market["id"]
	}
	var response map[string]any = nil
	if (marketType != nil && *marketType == "spot") || (marketType != nil && *marketType == "margin") {

		r1 := <-this.PrivateSpotGetMarginPositions(this.Extend(request, query))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else if marketType != nil && *marketType == "swap" {

		r2 := <-this.PrivateSwapGetAccountPositions(this.Extend(request, query))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	} else {
		panic(NotSupported(this.Id + " fetchPositions() not support this market type"))
	}
	//
	// swap
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "instrument_id": "BTCUSDTPERP",
	//                 "margin_mode": "crossed",
	//                 "avail_position": "1",
	//                 "avg_cost": "18369.3",
	//                 "last": "18404.7",
	//                 "leverage": "20",
	//                 "liquidation_price": "451.12820512820264",
	//                 "maint_margin_ratio": "0.005",
	//                 "margin": "0.918465",
	//                 "position": "1",
	//                 "realized_pnl": "0",
	//                 "unrealized_pnl": "0.03410000000000224",
	//                 "unrealized_pnl_rate": "0.03712716325608732",
	//                 "side": "long",
	//                 "open_outstanding": "0",
	//                 "risk_score": "0.495049504950495",
	//                 "margin_ratio": "0.4029464788983229",
	//                 "timestamp": 1667960497145
	//             },
	//             ...
	//         ]
	//     }
	//
	// margin
	//
	//     {
	//         "margin": "77.71534772983289",
	//         "code": 0,
	//         "margin_rate": "10.284503769497306",
	//         "positions": [
	//             {
	//                 "amount": 0.0010605,
	//                 "side": "go_long",
	//                 "entry_price": 18321.39,
	//                 "liquidation_rate": 0.3,
	//                 "liquidation_price": -52754.371758471,
	//                 "unrealized_roe": -0.002784390267332,
	//                 "symbol": "BTC_USDT",
	//                 "unrealized_pnl": -0.010820048189999,
	//                 "leverage_ratio": 5
	//             },
	//             ...
	//         ],
	//         "unrealized_pnl": "-0.10681600018999979"
	//     }
	//
	var positionRequest string = "positions"
	if marketType != nil && *marketType == "swap" {
		positionRequest = "data"
	}
	var positions []any = SafeListTyped(response, positionRequest)
	var result []any = []any{}
	for i := 0; i < len(positions); i++ {
		result = append(result, PositionToMap(this.ParsePosition(positions[i], market)))
	}

	ch <- AsyncResult[[]Position]{Value: PositionsFromList(this.FilterByArrayPositions(result, "symbol", symbolsNormalized))}
	return nil
}

